import {SCENARIOS,ACTIONS,CHAPTERS,SOURCES,MEMORY_CARDS} from './content.js';
import {createState,startAction,advance,compression,breath,inject,guidance,score,fmt,ROLES,holder,holdLabel,has,issue,addLog,isCritical} from './engine.js';
import {INTRO_STEPS,createIntro,runIntroStep} from './intro.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const amap=Object.fromEntries(ACTIONS.map(a=>[a.id,a]));
const ICONS={cross:'M12 3v18M3 12h18',arrow:'M4 12h16m-6-6 6 6-6 6',book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4zM12 6v15',play:'m8 4 12 8-12 8z',clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',check:'m5 12 4 4L20 5',pulse:'M2 12h5l3-8 4 16 3-8h5',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12 0l2 5M4 12l2 5a7 7 0 0 0 12 0',close:'m6 6 12 12M18 6 6 18'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[n]||ICONS.cross}"/></svg>`;
let view='home',S=null,role='main',cat='現場',filter='全部',search='',modal=null,checkpoints=[],lastFocus=null,limit=0,randomCase=false,toastTimer,history=[],cardIndex=0,cardHidden=false;
let introIndex=0,introFeedback='',introSnapshots=[];
try{history=JSON.parse(localStorage.getItem('emt.history')||'[]');if(!Array.isArray(history))history=[];}catch{}
const EXAM_SOURCES=[
 ['旺英基金會','學科、術科各 76 分；各一次即時補考。本班照片另有 OHCA／情境各至少 19／25。','https://www.wangyingfoundation.org/course-detail5-521-0.htm'],
 ['門諾醫院 2026','筆試 40 題×2，滿分 80 且要求 80／80；提示修正後再答。術科強調回覆示教、修正再考。','https://www.mch.org.tw/News/11684/Default.aspx'],
 ['北護大 115 年初訓','學科、術科各至少 70 分，各一次補考；課程包含半情境與全情境。','https://tueec.ntunhs.edu.tw/outer/CourseDetail/6644'],
 ['臺中紅十字會 115 年','學科、術科各 70 分，各一次補考。不能套用來取代本班的 76 分。','https://webredcross.sino1.com.tw/UploadURL.aspx?ApName=ContentDescFile&uid=1142'],
 ['內政部替代役訓練 FAQ','筆試 40%、實作 60%；實作含 CPR／AED 與止血包紮。','https://dca.moi.gov.tw/chaspx/Faq_Detail.aspx?id=6660&web=85'],
];
function header(){return `<header class="topbar"><button class="brand" data-view="home" aria-label="回到演練室首頁"><span class="brand-mark">${icon('pulse')}</span><span><b>救護演練室</b><small>EMT-1 SIMULATION LAB</small></span></button><nav class="nav" aria-label="主要導覽">${[['home','情境演練'],['notes','精華講義'],['cards','隨身卡'],['map','流程地圖'],['history','練習紀錄']].map(([v,t])=>`<button data-view="${v}" class="${view===v?'active':''}">${t}</button>`).join('')}</nav></header>`;}
function footer(){return `<footer class="footer"><span>依課程照片 × 消防署 × AHA 整理 · 核對日期 2026.11.07</span><span>流程練習｜實體手技需假人／教官確認 <button data-cmd="sources" style="text-decoration:underline">資料與規則</button></span></footer>`;}
function render(){
 const top=view==='intro'?`<header class="topbar"><button class="brand" data-view="home"><span class="brand-mark">${icon('pulse')}</span><span><b>救護演練室</b><small>第一次，我帶你走。</small></span></button><button class="btn small" data-view="home">回到首頁</button></header>`:header();
 $('#app').innerHTML=top+(view==='home'?home():view==='intro'?introPage():view==='sim'?simulation():view==='notes'?notes():view==='cards'?cardsPage():view==='map'?flowmap():view==='report'?report():historyPage())+footer();
 if(view==='sim')updateAll();
}
function savedState(){try{const v=JSON.parse(localStorage.getItem('emt.session')||'null');return v?.schema===2&&!v.state.ended?v:null;}catch{return null;}}
function advancedHome(){return `<main class="wrap"><div class="hero"><div><div class="eyebrow"><span class="dot"></span> 從「我現在該做什麼」開始</div><h1>把流程練進手裡，<br>讓主副手<em>接得起來。</em></h1><p>進入現場、評估患者、指派隊友、拿器材與執行處置。患者會改變，你也要跟著改變流程。先帶練，再進考場。</p><div class="button-row" style="margin-top:22px"><button class="btn primary" data-start="ohca">${icon('play')}從 OHCA 開始</button><button class="btn" data-cmd="random">抽一題進考場 ${icon('arrow')}</button>${savedState()?'<button class="btn" data-cmd="resume">接續上次演練</button>':''}</div></div><aside class="hero-side"><div class="mini-title">ONE SCENE. TWO RESCUERS.</div><h2>你負責決定，<br>隊友負責接上。</h2><div class="hero-flow"><span>現場</span> → <span>評估</span> → <span>處置</span> → <span>重評</span></div><div style="margin-top:20px;font-size:11px;color:#a7c5b8">12 個情境 · 並行分工 · 動態分支 · 操作回放</div></aside></div><div class="section-head"><div><h2>今天，從哪個現場開始？</h2><p style="margin-top:7px">老師指定的 11 題，加上獨立 OHCA 流程測驗。</p></div><div class="pill-group" aria-label="情境分類">${['全部','OHCA','非創傷','創傷'].map(t=>`<button data-filter="${t}" class="${filter===t?'selected':''}">${t}</button>`).join('')}</div></div><div class="scenario-grid">${SCENARIOS.filter(s=>filter==='全部'||s.type===filter).map((s)=>`<button class="case-card" data-start="${s.id}"><div class="case-body"><div class="case-top"><span class="tag ${s.type==='OHCA'?'ohca':''}">${s.type}</span><span class="case-index">${String(SCENARIOS.indexOf(s)+1).padStart(2,'0')}</span></div><h3>${s.name}</h3><p>${s.dispatch}</p></div><div class="case-foot"><span>${s.id==='ohca'?'逐項對照評分表':'主副手完整情境'}</span><span>進入現場 ↗</span></div></button>`).join('')}</div><div class="intro-note">${icon('shield')}<div><b>考場規則有來源，練習標準有標示。</b><br>OHCA 依你提供的 25 分評分表對照；其他情境採嚴格流程檢核。網站不會由點擊捏造真實按壓深度、回彈或吹氣品質。未提供正式情境評分表的部分，會明確標示為練習規則。</div></div></main>`;}
function home(){return `<main class="wrap newbie-home"><div class="eyebrow"><span class="dot"></span> 第一次來，從這裡開始就好。</div><h1>先知道下一步，<br>再把整套練起來。</h1><p class="newbie-lead">現在不用找器材，也不用自己切換主副手。<br>我一次只帶你做一件事，告訴你誰做、怎麼說、為什麼。</p><button class="btn primary newbie-start" data-cmd="intro">${icon('play')}我是新手，帶我走一次 OHCA</button><div class="newbie-path"><div><span>1</span><b>跟著走</b><p>一次只看目前這一步。</p></div><div><span>2</span><b>看懂分工</b><p>主手、副手各做什麼。</p></div><div><span>3</span><b>練會跳轉</b><p>何時 CPR？何時只通氣？</p></div></div><p class="small">閱讀時不倒數、不評分。完整模擬和嚴格規則都還在，熟悉後再進去。</p><div class="button-row" style="margin-top:20px"><button class="btn" data-view="cards">先看隨身記憶卡</button><button class="btn" data-view="notes">看精華講義</button></div><details class="advanced-options"><summary>我已經熟悉操作：展開 12 個完整情境</summary>${advancedHome().replace(/^<main\b/,'<div').replace(/<\/main>$/,'</div>')}</details></main>`;}
function introPage(){
 if(!S?.intro)S=createIntro();
 const step=INTRO_STEPS[introIndex];
 if(!step)return `<main class="intro-wrap"><div class="eyebrow">第一輪，走完了。</div><h1>先把這三條路記住。</h1><div class="intro-summary"><div><b>沒有正常呼吸，也沒有確定脈搏</b><p>CPR 30：2 ＋ AED。</p></div><div><b>有脈搏，但呼吸不足</b><p>BVM 每六秒一口，約每兩分鐘重評脈搏。</p></div><div><b>有脈搏，也有正常呼吸</b><p>持續監測、照護與後送；變化隨時回 ABC。</p></div></div><p class="newbie-lead">你剛剛走的是教學示範，沒有計考試分數。<br>接下來可以再跟一次，或進完整帶練慢慢操作。</p><div class="button-row"><button class="btn primary" data-cmd="intro-full">進入完整 OHCA 帶練</button><button class="btn" data-cmd="intro">再跟一次</button></div></main>`;
 const exercise=step.exercise==='cycle';
 const exerciseOK=exercise?S.cpr.cycles>=1:step.exercise==='one-breath'?!!S.flags.intro_one_breath:true;
 return `<main class="intro-wrap"><div class="intro-progress"><span>OHCA 新手導讀</span><span>第 ${introIndex+1} / ${INTRO_STEPS.length} 步</span></div><div class="intro-track"><i style="width:${(introIndex/INTRO_STEPS.length)*100}%"></i></div>${introFeedback?`<div class="intro-feedback" role="status">${icon('check')}<span>${esc(introFeedback)}</span></div>`:''}<section class="intro-step"><span class="tag">這一步：${esc(step.who)}</span><h1>${esc(step.title)}</h1><div class="intro-roles"><div><b>主手現在做什麼</b><p>${esc(step.main)}</p></div><div><b>副手現在做什麼</b><p>${esc(step.sub)}</p></div></div><p class="intro-why">${esc(step.why)}</p><div class="intro-say"><span>跟著說這句</span><p>「${esc(step.say)}」</p><button class="btn small" data-cmd="intro-say">聽一次口令</button></div>${exercise?`<div class="intro-exercise"><p>先按深色區 30 次，再給兩口。這裡只練節奏與分工。</p><div class="resus-controls"><button class="tap-pad" id="intro-tap" data-cmd="intro-press" ${S.cpr.count>=30||S.cpr.cycles>=1?'disabled':''}><strong>${S.cpr.cycles>=1?'30 下完成':S.cpr.count+' / 30'}</strong><small>主手：按壓一次</small></button><button class="tap-pad breath" data-cmd="intro-breath" ${S.cpr.count<30||S.cpr.cycles>=1?'disabled':''}><strong>${S.cpr.cycles>=1?'2 口完成':S.cpr.breaths+' / 2'}</strong><small>副手：給一口 BVM</small></button></div><p class="small" style="margin-top:12px">目前螢幕節奏 ${S.cpr.rate||'—'} 下／分；目標 100–120。真實深度、回彈與胸起另用假人確認。</p></div>`:step.exercise==='one-breath'?`<div class="intro-exercise"><button class="btn lime" data-cmd="intro-breath" ${exerciseOK?'disabled':''}>${exerciseOK?'已給一口，下一口約六秒後':'副手：給一口 BVM'}</button></div>`:''}<button class="btn primary intro-next" data-cmd="intro-next" ${exerciseOK?'':'disabled'}>${esc(step.button)} ${icon('arrow')}</button><p class="label-note" style="margin-top:12px">這是導讀：閱讀時不倒數；指定的重複段落會由示範代演或快轉。完整模式由你自行操作。</p></section><div class="intro-bottom"><button class="btn small" data-cmd="intro-back" ${introIndex===0?'disabled':''}>← 回上一步</button><button class="btn small" data-cmd="intro">從頭再走</button></div></main>`;
}
function startIntro(){closeDialog();S=createIntro();introIndex=0;introFeedback='';introSnapshots=[];view='intro';render();window.scrollTo(0,0);}
function introNext(){const before=structuredClone(S);try{const result=runIntroStep(S,introIndex);introSnapshots.push({state:before,feedback:introFeedback});introFeedback=result;introIndex++;render();window.scrollTo(0,0);}catch(e){S=before;toast(e.message);}}
function startDialog(id,isRandom=false){
 const sc=SCENARIOS.find(s=>s.id===id);randomCase=isRandom;
 showDialog(`<div class="dialog-head"><div><div class="eyebrow">${isRandom?'BLIND SCENARIO':'SCENE BRIEFING'}</div><h2 style="margin-top:8px">${isRandom?'未知情境抽題':esc(sc.name)}</h2></div><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body"><p>${esc(sc.dispatch)}</p><label class="field">演練方式<select id="start-mode"><option value="coach">帶練：看主副手提示與操作要領</option><option value="exam" ${isRandom?'selected':''}>考場：隱藏提示，自己安排操作</option></select></label><label class="field">自訂壓力練習時間（分鐘，0 為不限時）<input id="start-limit" type="number" min="0" max="120" value="0"></label>${sc.id==='ohca'?'<label class="field">心律劇情<select id="start-variant"><option value="default">VF：建議電擊</option><option value="pea">PEA：不建議電擊，仍無脈搏</option></select></label>':sc.id==='hypo'?'<label class="field">患者狀態<select id="start-variant"><option value="default">清醒，可安全吞嚥</option><option value="coma">無反應，不能口服</option></select></label>':sc.id==='chestinjury'?'<label class="field">胸傷類型<select id="start-variant"><option value="default">開放胸傷，沒有留置異物</option><option value="foreign">留置異物，原位固定</option></select></label>':''}<div class="callout"><b>操作方式</b><br>你可以切換主手／副手，或直接把操作指派給另一位。兩人各有自己的時間與雙手；持續固定、加壓或 BVM 密合時，先交接才能離手。患者數值需要評估才會出現。<br>沒有查到本班單站正式時限，因此倒數為自訂練習，並非考規。</div></div><div class="dialog-footer"><button class="btn" data-cmd="close">返回</button><button class="btn primary" data-begin="${id}">${icon('play')}開始完整演練</button></div>`,'brief');
}
function begin(id){
 const mode=$('#start-mode').value,variant=$('#start-variant')?.value;limit=Math.max(0,Math.min(120,Number($('#start-limit').value)||0))*60;
 S=createState(id,mode);S.limit=limit;S.blind=randomCase;role='main';cat='現場';checkpoints=[];
 if(variant==='pea')S.scenario={...S.scenario,rhythm:'PEA'};
 if(variant==='coma'){S.p.gcs=3;S.scenario={...S.scenario,look:'患者倒在沙發上，冒冷汗、無法喚醒。',response:'呼叫拍肩無反應。',required:['glucose','als','transport']};}
 if(variant==='foreign')S.scenario={...S.scenario,look:'右胸留有一塊金屬片，患者喘且疼痛。',required:['expose','lung','oxygen','foreign_fix','als']};
 addLog(S,'派遣',S.scenario.dispatch,'info');closeDialog();view='sim';render();window.scrollTo(0,0);persist();
}
function patientSVG(){return `<svg viewBox="0 0 230 315" role="img" aria-label="患者示意圖，點擊身體區域可開啟相關評估"><defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0v20" fill="none" stroke="#c3d6c6" stroke-width=".4"/></pattern></defs><rect width="230" height="315" fill="url(#grid)"/><ellipse cx="115" cy="44" rx="23" ry="28" class="body-zone" data-zone="head" tabindex="0" role="button" aria-label="頭部：反應與呼吸道"/><path class="body-zone" data-zone="neck" tabindex="0" role="button" aria-label="頸部：頸椎與頸部檢查" d="M104 70h22v18h-22z"/><path class="body-zone" data-zone="chest" tabindex="0" role="button" aria-label="胸部：呼吸循環與按壓" d="M80 88q35-12 70 0l9 84H71z"/><path class="body-zone" data-zone="abdomen" tabindex="0" role="button" aria-label="腹部：暴露與身體檢查" d="M71 174h88l-7 34H78z"/><path class="body-zone" data-zone="limb" tabindex="0" role="button" aria-label="上肢：出血與骨折" d="m77 90-14 2-18 91 13 4 22-69zm76 0 14 2 18 91-13 4-22-69z"/><path class="body-zone" data-zone="limb" tabindex="0" role="button" aria-label="下肢：出血與骨折" d="M80 210h31l-7 83H83zm39 0h31l-3 83h-22z"/><path d="M115 100v65M88 120h54M90 138h50" stroke="#8db5a3" stroke-width="1" opacity=".65"/><circle cx="115" cy="145" r="12" fill="none" stroke="#087c70" stroke-dasharray="3 3"/><text x="115" y="309" text-anchor="middle" fill="#749487" font-size="7" font-family="monospace">PATIENT ASSESSMENT ZONES</text></svg>`;}
function simulation(){if(!S)return home();return `<div class="sim-top"><div class="sim-title"><div class="eyebrow"><span class="dot"></span> ${S.mode==='coach'?'GUIDED PRACTICE · 帶練':'EXAM SIMULATION · 考場'}</div><h1>${S.blind?'未知情境':esc(S.scenario.name)}</h1></div><div class="clock-tools"><span class="timer" id="clock">${fmt(S.time)}</span><button class="btn small" data-cmd="pause" id="pause-label">暫停</button><button class="btn small" data-cmd="advance">推進 10 秒</button><select id="speed" aria-label="模擬時間速度" class="btn small"><option value="1" ${S.speed===1?'selected':''}>1× 時間</option><option value="3" ${S.speed===3?'selected':''}>3× 時間</option><option value="10" ${S.speed===10?'selected':''}>10× 時間</option></select><button class="btn small" data-cmd="map-dialog">跳轉地圖</button><button class="btn small danger" data-cmd="finish">交接／結束</button></div></div><main class="sim-layout"><aside class="left-col stack"><section class="scene-card"><div class="dispatch-label">DISPATCH / 現場資訊</div><h2>${esc(S.scenario.dispatch)}</h2><p>${esc(S.scenario.look)}</p></section><section class="panel"><div class="panel-head"><h2>目前的流程位置</h2><button data-cmd="map-dialog" aria-label="展開流程地圖">↗</button></div><div id="flow-position">${flowPosition()}</div></section><div class="branch-card"><strong>先處理威脅，再接續流程</strong>大出血先止血；沒有正常呼吸與脈搏就跳 OHCA；有脈搏而通氣不足走 BVM。患者改變，隨時回 ABC。</div><div class="button-row"><button class="btn small" data-cmd="mode">${S.mode==='coach'?'切成考場':'開啟帶練'}</button><button class="btn small" data-cmd="instructor">考官事件</button></div><p class="label-note">病況惡化時間為教學劇情設定。螢幕操作練順序，真實手技用假人確認。</p></aside><section class="center-col stack"><section class="panel"><div class="panel-head"><h2>${icon('pulse')} 患者評估台</h2><span class="tag" id="branch-tag">評估中</span></div><div class="patient"><span class="patient-label">OBSERVE · ASSESS · ACT</span><div class="patient-art">${patientSVG()}</div><div class="patient-note"><b>先評估，才有資訊。</b>點身體部位，打開對應操作。<br><br>生命徵象只顯示你已檢查或監測到的結果。</div></div><div id="patient-readouts"></div><div id="resus-console"></div></section><section class="panel"><div class="panel-head"><h2>患者與考官回應</h2><span class="small">依你的操作更新</span></div><div id="responses"></div></section></section><aside class="right-col stack"><section class="panel"><div class="panel-head"><h2>兩位隊員，同時進行</h2><span class="tag">並行任務</span></div><div id="crew"></div></section><section class="panel"><div class="panel-head"><h2>操作與器材</h2><span class="small">${ACTIONS.length} 項</span></div><div class="panel-body" style="padding-bottom:8px"><div class="role-toggle"><button data-role="main" class="${role==='main'?'on':''}">主手操作</button><button data-role="sub" class="${role==='sub'?'on':''}">副手操作</button></div><input class="action-search" id="action-search" placeholder="找操作，例如：血糖、AED、止血" aria-label="搜尋操作" value="${esc(search)}"></div><div class="action-tabs">${['現場','評估','處置','器材','急救','溝通'].map(c=>`<button data-cat="${c}" class="${c===cat?'on':''}">${c}</button>`).join('')}</div><div class="action-list" id="action-list">${actionList()}</div></section><section class="panel"><div class="panel-head"><h2>操作紀錄</h2><button class="small" data-cmd="log-full">完整紀錄 ↗</button></div><div class="log" id="live-log"></div></section></aside></main>`;}
function flowPosition(){let stage=!has(S,'safe')||!has(S,'help')?0:!has(S,'bpcheck')?1:S.knownArrest||S.branch==='ventilation'?2:!has(S,'transport')?3:!has(S,'secondary')?4:5;const names=['現場常規與求援','初評：意識、XABCDE','立即救命處置／OHCA','危急判斷、準備後送','二度評估與病史','持續重評、通報交接'];return `<ol class="flow-list">${names.map((t,i)=>`<li data-n="${i+1}" class="${i===stage?'current':i<stage?'done':''}">${t}</li>`).join('')}</ol>`;}
function actionList(){const rec=guidance(S)[role];const list=ACTIONS.filter(a=>search?a.title.toLowerCase().includes(search.toLowerCase()):a.cat===cat);return list.length?list.map(a=>`<button class="action-button ${has(S,a.id)?'done-action':''} ${S.mode==='coach'&&rec.slice(0,3).includes(a.id)?'recommended':''}" data-action="${a.id}"><span>${a.title}</span><span class="metadata">${has(S,a.id)?'已做 · ':''}${a.sec} 秒</span></button>`).join(''):'<p class="no-data">沒有符合的操作，試試「血糖」「止血」或「AED」。</p>';}
function readouts(){
 const o=S.observed,v=o.vitals,hr=o.pulse?o.pulse.hr:v?.hr,rr=o.breathing?.rr??v?.rr;
 const num=x=>x===undefined?'—':x;
 return `<div class="vital-grid"><div class="vital"><small>脈搏 HR</small><strong class="${hr!==undefined&&(hr<50||hr>150)?'alert':''}">${num(hr)}</strong><span class="unit">/min</span></div><div class="vital"><small>呼吸 RR</small><strong class="${rr!==undefined&&(rr<10||rr>=30)?'alert':''}">${num(rr)}</strong><span class="unit">/min</span></div><div class="vital"><small>血氧 SpO₂</small><strong class="${v?.spo2<90?'alert':''}">${v?(v.hr===0?'無讀值':v.spo2):'—'}</strong><span class="unit">%</span></div><div class="vital"><small>血壓 BP</small><strong class="${v?.sbp<90?'alert':''}" style="font-size:20px">${v?(v.hr===0?'無讀值':v.sbp+'/'+v.dbp):'—'}</strong></div></div>${v?`<div class="no-data" style="padding-top:5px;padding-bottom:8px">最近量測 ${fmt(v.t)}；數值是當時結果，病況改變須重評。</div>`:''}${o.conscious?`<div class="observation"><strong>意識與反應 · ${fmt(o.conscious.t)}</strong>${esc(o.conscious.text)} ${has(S,'gcs')?'GCS '+o.conscious.gcs+'/15':''}</div>`:''}${o.glucose?`<div class="observation"><strong>血糖 · ${fmt(o.glucose.t)}</strong>${o.glucose.value} mg/dL</div>`:''}${o.airway?`<div class="observation"><strong>A 呼吸道</strong>${esc(o.airway)}</div>`:''}${o.breathing?`<div class="observation"><strong>呼吸與脈搏 · ${fmt(o.breathing.t)}</strong>${esc(o.breathing.text)} ${esc(o.pulse.text)}</div>`:''}${o.bleeding?`<div class="observation"><strong>X 出血評估</strong>${esc(o.bleeding)}</div>`:''}${!Object.keys(o).length?'<p class="no-data">患者資料尚未量測。請先完成現場常規，再接近評估。</p>':''}`;
}
function crew(){const g=guidance(S);return ['main','sub'].map(r=>{const t=S.tasks[r],h=S.holds[r],rec=g[r][0];return `<div class="crew"><div class="crew-title"><span class="avatar ${r==='sub'?'sub':''}">${r==='main'?'01':'02'}</span><b>${ROLES[r]}</b><span style="margin-left:auto" class="small">${t?'操作中':h?'持續占手':'可接受任務'}</span></div><div class="crew-status" id="status-${r}">${t?esc(amap[t.id].title)+' · 剩 '+t.remaining+' 秒':h?'持續'+holdLabel(h):'等待明確指令'}</div>${t?`<div class="task-track"><i id="progress-${r}" style="width:${(1-t.remaining/t.total)*100}%"></i></div><button class="btn small" style="margin-top:10px" data-cancel="${r}">中止目前操作</button>`:h?`<div class="button-row" style="margin-top:8px"><button class="btn small" data-transfer="${r}">交接給${ROLES[r==='main'?'sub':'main']}</button><button class="btn small" data-release="${r}">暫停／離手</button></div>`:''}${S.mode==='coach'&&rec?`<div class="task-guide">接下來可做：<button data-action="${rec}" data-actor="${r}">${esc(amap[rec]?.title||rec)} ↗</button></div>`:''}</div>`;}).join('');}
function resus(){if(!S.knownArrest&&!has(S,'bvm')&&!S.aed.power)return '';return `<div class="resus"><h3>急救操作台 <span class="tag">${S.branch==='ventilation'?'有脈搏 · 呼吸支持':'30:2 · 無進階呼吸道'}</span></h3><div class="resus-controls"><button class="tap-pad" id="tap-cpr" data-cmd="compression"><strong id="compress-count">${S.cpr.count} / 30</strong><small>按一下＝一次螢幕節奏練習 <span class="key-hint">空白鍵</span></small></button><button class="tap-pad breath" data-cmd="breath"><strong id="breath-count">BVM ${S.cpr.breaths} / 2</strong><small>每口約 1 秒、看胸起；有脈搏每 6 秒一口</small></button></div><div class="cpr-stats"><span id="cpr-rate">節奏：${S.cpr.rate||'—'} 下／分</span><span id="cpr-cycles">完成循環：${S.cpr.cycles}</span><span>按壓者：${holder(S,'cpr')?ROLES[holder(S,'cpr')]:'未就位'}</span><span>通氣者：${holder(S,'bvm')?ROLES[holder(S,'bvm')]:'未就位'}</span></div><p class="label-note" style="margin-top:9px">這裡只練時序與節奏，不能測到真實胸深、回彈與胸起。</p>${S.aed.power?`<div class="aed-console"><b style="font-size:12px">AED ${S.aed.result==='shock'?'· 建議電擊':S.aed.result==='no-shock'?'· 不建議電擊':'· 已開機'}</b><p>${S.aed.pads?'貼片已接妥':'貼片尚未接妥'} · ${S.aed.cleared?'已清場':'仍需確認清場'} · 已分析 ${S.aed.analyses} 次</p><div class="button-row">${['aed_pads','clear','aed_analyze','shock','cpr','bvm','opa','postcheck'].map(id=>`<button class="btn small ${id==='shock'&&S.aed.result==='shock'?'danger':''}" data-action="${id}" data-actor="${amap[id].role==='main'?'main':'sub'}">${amap[id].title.split('、')[0]}</button>`).join('')}</div></div>`:''}</div>`;}
function responses(){let o=S.observed;let fields=[['肺音與呼吸作功',o.lung],['病史／OPQRST',o.history],['G-FAST',o.gfast],['最後正常時間',o.lastwell],['吞嚥評估',o.swallow],['頸部',o.neck],['遠端 PSM',o.psm],['燒傷',o.burn],['胸傷處理',o.chest]];let n=S.announcements.at(-1);return `${n?`<div class="decision-summary" style="background:#f1f6e8"><b>${esc(n.title)} · ${fmt(n.t)}</b><br>${esc(n.text)}</div>`:''}${fields.filter(([,v])=>v).map(([k,v])=>`<div class="observation"><strong>${k}</strong>${esc(v)}</div>`).join('')}${!n&&!fields.some(([,v])=>v)?'<p class="no-data">完成評估後，患者／家屬與考官會在這裡回應。考場模式不會預先顯示診斷答案。</p>':''}`;}
function updateAll(){if(view!=='sim'||!S)return;$('#patient-readouts').innerHTML=readouts();$('#crew').innerHTML=crew();$('#resus-console').innerHTML=resus();$('#responses').innerHTML=responses();$('#flow-position').innerHTML=flowPosition();$('#action-list').innerHTML=actionList();$('#live-log').innerHTML=logs(S.log.slice(-10));updateLive();}
function updateLive(){if(view!=='sim'||!S)return;$('#clock').textContent=fmt(S.time)+(S.limit?' / '+fmt(S.limit):'');$('#pause-label').textContent=S.paused?'繼續':'暫停';$('#branch-tag').textContent={assessment:'一般評估',arrest:'OHCA 急救',ventilation:'有脈搏 · 通氣不足',rosc:'循環恢復後照護',change:'狀況改變 · 請重評'}[S.branch];for(const r of ['main','sub']){let t=S.tasks[r];if(t&&$('#status-'+r)){$('#status-'+r).textContent=amap[t.id].title+' · 剩 '+t.remaining+' 秒';const p=$('#progress-'+r);if(p)p.style.width=((1-t.remaining/t.total)*100)+'%';}}}
function openAction(id,actor=role){
 if(!S||S.ended)return;const a=amap[id];if(!a)return;role=actor;
 const wasPaused=S.paused;if(S.mode==='coach')S.paused=true;
 showDialog(`<div class="dialog-head"><div><div class="eyebrow">${a.cat} · ${a.phase} · 約 ${a.sec} 秒</div><h2 style="margin-top:8px">${esc(a.title)}</h2></div><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body">${S.mode==='coach'?`<ol class="step-list">${a.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="say"><small>練習時說出口</small><br>「${esc(a.voice)}」<button class="btn small" style="margin-top:10px" data-say="${id}">聽口令</button></div>`:`<p>指定執行者，依你學過的操作完成。考場模式隱藏步驟；需要時可在左側開啟帶練。</p>`}${id==='oxygen'?'<div class="field-row"><label class="field">氧氣裝置<select id="opt-device"><option value="nc">鼻導管 NC</option><option value="simple">簡單面罩</option><option value="nrm" selected>非再呼吸型面罩 NRM</option></select></label><label class="field">流量 L/min<input id="opt-flow" type="number" min="1" max="15" value="15"></label></div>':''}${['cpr','bvm'].includes(id)?'<div class="callout">就位後使用患者下方的按壓／BVM 操作台。真實位置、深度、回彈與胸起由假人、QCPR／教官確認。</div>':''}<div id="action-error"></div><p class="label-note" style="margin-top:16px">主副手分工依現場調整；持續占手的任務需要先交接。${S.mode==='coach'?'帶練閱讀時已暫停計時。':'考場閱讀時仍持續計時。'}</p></div><div class="dialog-footer"><button class="btn ${actor==='main'?'primary':''}" data-execute="${id}" data-actor="main">主手執行</button><button class="btn ${actor==='sub'?'primary':''}" data-execute="${id}" data-actor="sub">副手執行</button></div>`,'action',{wasPaused});
}
function execute(id,r){const opt={device:$('#opt-device')?.value,flow:$('#opt-flow')?.value};checkpoints.push({id,r,t:S.time,state:structuredClone(S)});if(checkpoints.length>80)checkpoints.shift();const result=startAction(S,id,r,opt);if(!result.ok){$('#action-error').innerHTML=`<div class="error-box">${esc(result.message)}</div>`;updateAll();persist();return;}closeDialog(false);role=r;toast(result.message);render();persist();}
function logs(ls,rewind=false){return ls.map((l,i)=>`<div class="log-item ${l.kind}"><time>${fmt(l.t)}</time><div><span class="who">${ROLES[l.who]||esc(l.who)}</span>${esc(l.text)}${rewind&&['warning','danger'].includes(l.kind)?`<button class="btn small" data-rewind="${l.t}">回到此處重練</button>`:''}</div></div>`).join('');}
function showDialog(html,type='info',meta={}){lastFocus=document.activeElement;modal={type,...meta};$('#drawer-root').innerHTML=`<div class="drawer-overlay"><section class="dialog ${type==='wide'?'wide':''}" role="dialog" aria-modal="true" aria-label="${type==='action'?'執行操作':'演練說明'}">${html}</section></div>`;$('#drawer-root').querySelector('button,input,select')?.focus();}
function closeDialog(restore=true){if(restore&&modal?.type==='action'&&S)S.paused=modal.wasPaused;$('#drawer-root').innerHTML='';modal=null;lastFocus?.focus?.();}
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function persist(){if(!S||S.intro)return;try{localStorage.setItem('emt.session',JSON.stringify({schema:2,state:S}));}catch{}}
function finish(){if(!S)return;S.ended=true;S.paused=true;addLog(S,'交接','結束本輪演練，開始回放。','info');saveHistory();persist();view='report';closeDialog(false);render();window.scrollTo(0,0);}
function saveHistory(){const result=score(S);const item={id:Date.now(),scenario:S.scenario.id,name:S.scenario.name,time:S.time,date:new Date().toLocaleString('zh-TW'),points:result.points,critical:S.issues.filter(x=>x.critical).length,missing:result.checks.filter(x=>!x.done).map(x=>x.title),issues:S.issues,log:S.log};S.historyId??=item.id;history=history.filter(x=>x.id!==S.historyId);item.id=S.historyId;history.unshift(item);history=history.slice(0,30);try{localStorage.setItem('emt.history',JSON.stringify(history));}catch{}}
function report(){if(!S)return historyPage();const r=score(S),q=r.ohca;return `<main class="wrap"><div class="section-head"><div><div class="eyebrow">AFTER ACTION REVIEW</div><h1 style="font-size:30px;margin-top:10px">把漏掉的地方，練回來。</h1><p style="margin-top:9px">${esc(S.scenario.name)} · ${fmt(S.time)} · ${S.mode==='exam'?'考場模式':'帶練模式'}</p></div><div class="button-row"><button class="btn" data-start="${S.scenario.id}">${icon('refresh')}再練一次</button><button class="btn primary" data-view="notes">查精華講義</button><button class="btn" data-cmd="export-log">下載操作紀錄</button></div></div><div class="debrief-banner"><div><b>${S.issues.some(i=>i.critical)?'嚴格練習：有重大風險操作，請先重練。':'先檢查漏項，再確認實體手技。'}</b><br>情境完成度與風險檢核是本網站的練習標準。OHCA 評分表另列；未實測手技不宣稱正式通過。</div><div class="score-big">${r.points}<small>流程練習 / 100</small></div></div><div class="report-grid"><section class="panel"><div class="panel-head"><h2>必要流程與情境項目</h2><span class="small">${r.checks.filter(c=>c.done).length}/${r.checks.length}</span></div><div class="panel-body">${r.checks.map(c=>`<div class="check-row"><span class="${c.done?'check':'miss'}">${c.done?'✓':'○'}</span><span>${esc(c.title)}</span><span class="time">${c.done?ROLES[c.who]+' '+fmt(c.t):'漏做'}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>需要修正的地方</h2><span class="small">${S.issues.length} 項</span></div><div class="panel-body">${S.issues.length?S.issues.map(i=>`<div class="check-row"><span class="${i.critical?'miss':'check'}">${i.critical?'!':'·'}</span><div><b>${fmt(i.t)} ${i.critical?'重大風險':'流程提醒'}</b><p>${esc(i.text)}</p>${checkpoints.length?`<button class="btn small" data-rewind="${i.t}">回到錯誤前重練</button>`:''}</div></div>`).join(''):'<p class="small">沒有記錄到被攔下的風險操作。仍須確認漏項、時序與實體操作品質。</p>'}<div class="callout">回放檢查：危急後是否及時啟動後送？救命處置是否被不必要檢查打斷？交接是否有接手確認？</div></div></section></div>${q?ohcaReport(q):''}<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>完整操作回放</h2><span class="small">按時間排序</span></div><div class="panel-body">${logs(S.log,true)}</div></section></main>`;}
function ohcaReport(q){return `<section class="chapter" style="margin-top:24px"><h2>OHCA：對照你提供的 25 分評分表</h2><p>這是照片評分項目的數位對照，動作標準與不標準仍需教官觀察。未實測欄位保持空白。</p><div class="report-grid"><div><table class="table"><thead><tr><th>項目</th><th>練習估計扣分</th></tr></thead><tbody>${q.rows.map(x=>`<tr><td>${x.name}</td><td>${x.deduct===null?'待實測':'−'+x.deduct}</td></tr>`).join('')}</tbody></table><p style="margin-top:12px"><b>${q.score===null?`已知扣分後上限 ${q.ceiling}/25；有 ${q.pending} 個實測欄位待確認。`:`表單估計 ${q.score}/25；${q.score>=19?'達到 19 分門檻，仍需教官核定。':'未達 19 分門檻，請重練。'}`}</b></p></div><div><h3>考官／QCPR 真實讀值</h3><p class="small">只能填實測，不把螢幕點擊當 QCPR。BLS 核心任何錯誤或至少兩項不標準，綜合扣 10；一項不標準扣 6。</p><form id="physical-form"><div class="field-row">${[['rate','頻率（下／分）',200],['depth','深度達標率（%）',100],['recoil','胸回彈率（%）',100]].map(([id,t,max])=>`<label class="field">${t}<input name="${id}" type="number" min="0" max="${max}" value="${esc(S.physical[id])}" placeholder="尚未實測"></label>`).join('')}</div>${[['placement','按壓位置'],['ventilation','BVM／30:2／有效胸起']].map(([id,t])=>`<label class="field">${t}<select name="${id}"><option value="">尚未實測</option>${[['0','標準'],['1','不標準'],['2','錯誤']].map(([v,t])=>`<option value="${v}" ${S.physical[id]===v?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}<button class="btn primary" type="submit">儲存實測結果</button></form></div></div></section>`;}
function notes(){return `<main class="wrap"><div class="section-head"><div><div class="eyebrow">FIELD NOTES / 嚴格版精華講義</div><h1 style="font-size:32px;margin-top:12px">一套骨架，十一個情境。</h1><p style="margin-top:10px">按流程學、按角色練。先把救命分支練順，再補完整評估。</p></div><div class="button-row"><a class="btn primary" href="emt-field-guide.pdf" target="_blank" download>${icon('book')}下載 PDF 講義</a><button class="btn" data-cmd="print">列印此頁</button></div></div><div class="notes-layout"><nav class="notes-index" aria-label="講義目錄">${CHAPTERS.map((c,i)=>`<a href="#chapter-${i}">${i+1}. ${c.title}</a>`).join('')}<a href="#cases-notes">老師指定的 11 題</a><a href="#exam-compare">各單位考核比較</a><a href="#sources-notes">資料來源</a></nav><article><div class="print-only"><h1>EMT-1 救護演練室｜精華講義</h1><p>核對日期 2026-11-07；依課程照片與官方指引整理。</p></div>${CHAPTERS.map((c,i)=>`<section class="chapter" id="chapter-${i}"><h2>${i+1}. ${c.title}</h2>${c.text.map(t=>`<p>${esc(t)}</p>`).join('')}</section>`).join('')}<div id="cases-notes"></div>${SCENARIOS.map((sc,i)=>`<section class="chapter" id="case-${sc.id}"><div class="eyebrow">${String(i).padStart(2,'0')} / ${sc.type}</div><h2 style="margin-top:8px">${sc.name}</h2><p>${esc(sc.dispatch)}</p><div class="roles-table"><div><b>主手</b>${sc.main}</div><div><b>副手</b>${sc.sub}</div></div><h3>考場要說、要做</h3><ol class="step-list">${sc.focus.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><h3>最容易漏掉</h3><ul>${sc.avoid.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>情境必要操作</h3><p>${sc.required.map(id=>amap[id]?.title||id).join(' → ')}。這是操作檢核清單；實際時序依 ABC 威脅與雙人分工調整。</p><button class="btn no-print" data-start="${sc.id}">進入這個情境 ${icon('arrow')}</button></section>`).join('')}<section class="chapter" id="exam-compare"><h2>其他單位怎麼考？</h2><p>公開簡章的分數、配分不同；以下僅供加嚴練習參考，不取代你這班的考規。未找到可核實的本班單站正式時限。</p><div class="sources">${EXAM_SOURCES.map(([n,t,u])=>`<div class="source"><b>${n}</b>${t}<br><a href="${u}" target="_blank" rel="noopener">官方考核說明 ↗</a></div>`).join('')}</div><h3>本網站的加嚴練習門檻</h3><p>無提示完成評估、生命威脅發現即處理、主副手不違反占手限制、給氧／通氣／AED 安全、情境必要操作與處置後重評、支援與後送不中斷。重大風險操作標記「需重練」，這是自訂學習門檻。</p></section><section class="chapter" id="sources-notes"><h2>資料來源與適用範圍</h2>${sourcesHTML()}</section></article></div></main>`;}
function mapContent(){return `<div class="flow-map"><div class="flow-node">現場安全、防護、人數與 119<br>創傷同步保護頸椎，致命外出血在 X 立即處理</div><div class="flow-node">確認反應 → 暢通呼吸道<br><b>同時檢查正常呼吸與脈搏，10 秒內</b></div><div class="flow-branches"><div><div class="flow-node urgent"><b>無正常呼吸＋無確定脈搏</b><br>立即 CPR 30:2＋AED</div><div class="flow-node" style="margin-top:10px">AED：清場 → 分析<br>建議電擊：清場、電擊、立即 CPR<br>首次不電擊：立即 CPR<br>不電擊不等於恢復心跳</div></div><div><div class="flow-node urgent"><b>有脈搏＋呼吸不足</b><br>BVM 每 6 秒一口<br>約每 2 分鐘重評脈搏</div><div class="flow-node" style="margin-top:10px"><b>有脈搏＋正常呼吸</b><br>接續初評／循環恢復後照護<br>必要處置、支援與後送</div></div></div><div class="flow-node">任何時刻出現變化 → 立即回 ABC／呼吸脈搏<br>危急者先準備後送；二度評估與病史可以並行</div><div class="flow-node">八大徵象、病史、身體檢查 → 重評 → 通報交接<br>教材：危急每 5 分鐘／非危急每 15 分鐘，變化隨時重評</div></div>`;}
function flowmap(){return `<main class="wrap" style="max-width:1040px"><div class="section-head"><div><div class="eyebrow">WHEN TO SWITCH</div><h1 style="font-size:30px;margin-top:10px">什麼時候，直接跳哪裡？</h1></div><button class="btn primary" data-start="ohca">進入操作練習</button></div>${mapContent()}<div class="callout">你的課程表在第二次之後 AED 不建議電擊時要求快速評估脈搏；新版 AHA 強調不中斷 CPR 並依生命跡象重評。共同原則：沒有確定脈搏不能停止 CPR，有脈搏後仍要評呼吸。</div></main>`;}
function sourcesHTML(){return `<div class="sources">${SOURCES.map(([n,t,u])=>`<div class="source"><b>${n}</b>${esc(t)}${u?`<br><a href="${u}" target="_blank" rel="noopener">查看官方資料 ↗</a>`:''}</div>`).join('')}</div>`;}
function cardsPage(){const c=MEMORY_CARDS[cardIndex];return `<main class="wrap" style="max-width:1150px"><div class="section-head"><div><div class="eyebrow">POCKET NOTES / A6 隨身記憶卡</div><h1 style="font-size:30px;margin-top:12px">一張卡，抓住一個現場。</h1><p style="margin-top:10px">16 張卡。第 1 張 A4 是核心流程，後 3 張 A4 是情境與規則。</p></div><div class="button-row"><a class="btn primary" href="emt-a4-fourup.pdf" target="_blank" download>下載 A4 四格列印版</a><a class="btn" href="emt-a6-cards.pdf" target="_blank" download>下載單張 A6 版</a></div></div><div class="cards-layout"><nav class="notes-index" aria-label="隨身卡清單">${MEMORY_CARDS.map((c,i)=>`<button class="card-nav ${i===cardIndex?'on':''}" data-card="${i}">${String(i+1).padStart(2,'0')} ${esc(c.title.split('｜')[0])}</button>`).join('')}</nav><div><section class="pocket-card"><div class="eyebrow">${c.label} / EMT-1</div><h2>${esc(c.title)}</h2>${cardHidden?'<div class="card-recall"><p>先試著說出來：</p><b>主手做什麼？副手做什麼？<br>何時要改走別的流程？</b><button class="btn primary" data-cmd="card-flip">翻開對照</button></div>':c.blocks.map(([h,t])=>`<div class="card-block"><h3>${h}</h3><p>${esc(t)}</p></div>`).join('')}<div class="pocket-footer"><span>課程照片 × 官方指引 · 詳細做法看講義</span><span>${String(cardIndex+1).padStart(2,'0')} / 16</span></div></section><div class="button-row" style="margin-top:18px;justify-content:space-between"><button class="btn" data-cmd="card-prev">← 上一張</button><button class="btn" data-cmd="card-flip">${cardHidden?'顯示內容':'蓋住背誦'}</button><button class="btn" data-cmd="card-next">下一張 →</button></div>${SCENARIOS.some(s=>s.id===c.id)?`<button class="btn primary" style="margin-top:15px;width:100%" data-start="${c.id}">把這張卡練成完整情境 ${icon('arrow')}</button>`:''}<div class="callout">列印：A4 直式、實際大小／100%，每頁四張，沿虛線裁切或折成四面收納。單張 A6 版為 105 × 148 mm。記憶卡用來提醒，完整操作順序與差異請對照精華講義。</div></div></div></main>`;}
function historyPage(){return `<main class="wrap" style="max-width:1000px"><div class="section-head"><div><div class="eyebrow">PRACTICE JOURNAL</div><h1 style="font-size:30px;margin-top:12px">每次練習，都有留下。</h1><p style="margin-top:10px">只存在這台瀏覽器，最多保留 30 次。可以下載自己的完整操作紀錄。</p></div><button class="btn primary" data-view="home">開始下一輪</button></div>${history.length?history.map(h=>`<article class="history-card"><div class="section-head" style="margin:0"><strong>${esc(h.name)}</strong><span class="tag">流程練習 ${h.points}/100</span></div><p>${esc(h.date)} · ${fmt(h.time)} · ${h.critical} 個重大風險 · ${h.missing.length} 個漏項</p><div class="button-row"><button class="btn small" data-history="${h.id}">查看回放</button><button class="btn small" data-start="${h.scenario}">重新練習</button></div></article>`).join(''):'<section class="chapter"><h2>從第一輪開始。</h2><p>完成任一情境後，這裡會記錄流程完成度、漏項與風險操作。</p><button class="btn primary" data-start="ohca">開始 OHCA</button></section>'}</main>`;}
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function instructor(){showDialog(`<div class="dialog-head"><h2>考官事件控制台</h2><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body"><p>指定患者在此刻改變，練習被打斷後的流程切換。這些是教學劇情，不是固定疾病倒數。</p><div class="stack">${[['resp','呼吸停止／不足，仍有脈搏'],['arrest','突然無反應、無呼吸脈搏'],['noshock','下次 AED 不建議電擊，但仍無脈搏'],['rosc','恢復脈搏，但呼吸不足'],['normal','恢復脈搏與正常呼吸'],['unconscious','低血糖患者變無反應'],['sealworse','胸傷敷料後呼吸惡化']].map(([id,t])=>`<button class="btn" data-inject="${id}">${t}</button>`).join('')}</div><p class="label-note" style="margin-top:16px">考場模式使用此控制台會記錄「考官事件」。玩家仍須實際評估，畫面不直接揭露新的數值。</p></div>`,'instructor');}
function cmd(c){
 if(c==='intro'){startIntro();return;}
 if(c==='intro-next'){introNext();return;}
 if(c==='intro-back'){const old=introSnapshots.pop();if(old){S=old.state;introFeedback=old.feedback;introIndex--;render();}return;}
 if(c==='intro-full'){startDialog('ohca');return;}
 if(c==='intro-say'){if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(INTRO_STEPS[introIndex].say);u.lang='zh-TW';u.rate=.85;speechSynthesis.cancel();speechSynthesis.speak(u);}else toast('可直接依畫面的口令練習說出口。');return;}
 if(c==='intro-press'){const r=compression(S,performance.now());if(!r.ok)toast(r.message);render();return;}
 if(c==='intro-breath'){const r=breath(S,performance.now());if(!r.ok)toast(r.message);else if(INTRO_STEPS[introIndex]?.exercise==='one-breath')S.flags.intro_one_breath=true;render();return;}
 if(c==='close'){closeDialog();return;}
 if(c==='random'){startDialog(SCENARIOS[Math.floor(Math.random()*SCENARIOS.length)].id,true);return;}
 if(c==='resume'){const v=savedState();if(v){S=v.state;S.paused=true;limit=S.limit||0;view='sim';render();}return;}
 if(c==='sources'){showDialog(`<div class="dialog-head"><h2>資料與規則</h2><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body">${sourcesHTML()}</div>`);return;}
 if(c==='map-dialog'){showDialog(`<div class="dialog-head"><h2>流程跳轉地圖</h2><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body">${mapContent()}</div>`,'wide');return;}
 if(c==='print'){window.print();return;}
 if(c==='card-prev'||c==='card-next'){cardIndex=(cardIndex+(c==='card-next'?1:-1)+MEMORY_CARDS.length)%MEMORY_CARDS.length;cardHidden=false;render();return;}
 if(c==='card-flip'){cardHidden=!cardHidden;render();return;}
 if(!S)return;
 if(c==='pause'){S.paused=!S.paused;updateLive();persist();}
 if(c==='advance'){const before=S.log.length;advance(S,10);updateAll();persist();checkLimit();}
 if(c==='mode'){S.mode=S.mode==='coach'?'exam':'coach';if(S.mode==='coach')addLog(S,'系統','開啟帶練提示，此輪不視為無提示演練。','info');render();}
 if(c==='finish'){showDialog(`<div class="dialog-head"><h2>結束本輪，開始回放？</h2><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body"><p>記錄已做與漏掉的流程、角色分工、風險操作和時間。你也可以從錯誤前繼續重練。</p></div><div class="dialog-footer"><button class="btn" data-cmd="close">繼續演練</button><button class="btn primary" data-cmd="finish-now">交接並看回放</button></div>`);}
 if(c==='finish-now')finish();
 if(c==='instructor')instructor();
 if(c==='compression'){const r=compression(S,performance.now());if(!r.ok)toast(r.message);updateAll();}
 if(c==='breath'){const r=breath(S,performance.now());if(!r.ok)toast(r.message);else if(S.p.hr>0)toast('給 1 口通氣，觀察胸起；下一口約 6 秒後。');updateAll();}
 if(c==='log-full')showDialog(`<div class="dialog-head"><h2>完整操作紀錄</h2><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body">${logs(S.log)}</div>`,'wide');
 if(c==='export-log')download('EMT-'+S.scenario.id+'-'+Date.now()+'.json',JSON.stringify({scenario:S.scenario.name,time:S.time,score:score(S),issues:S.issues,log:S.log},null,2),'application/json;charset=utf-8');
}
document.addEventListener('click',e=>{
 const t=e.target.closest('button,a[data-cmd],[data-zone]');if(!t)return;
 if(t.dataset.view){if(view==='sim'&&S){S.paused=true;persist();}view=t.dataset.view;closeDialog();render();window.scrollTo(0,0);return;}
 if(t.dataset.filter){filter=t.dataset.filter;render();return;}
 if(t.dataset.start){startDialog(t.dataset.start);return;}
 if(t.dataset.begin){begin(t.dataset.begin);return;}
 if(t.dataset.cmd){cmd(t.dataset.cmd);return;}
 if(t.dataset.role){role=t.dataset.role;render();return;}
 if(t.dataset.cat){cat=t.dataset.cat;search='';render();return;}
 if(t.dataset.action){openAction(t.dataset.action,t.dataset.actor||role);return;}
 if(t.dataset.execute){execute(t.dataset.execute,t.dataset.actor);return;}
 if(t.dataset.zone){const groups={head:['response','airway','gcs','opa'],neck:['cspine','neck','collar','helmet'],chest:['bpcheck','lung','cpr','bvm','ecg','expose'],abdomen:['expose','secondary'],limb:['xcheck','pressure','tourniquet','psm','splint','psm_after']};showDialog(`<div class="dialog-head"><h2>選擇此部位的操作</h2><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body stack">${groups[t.dataset.zone].map(id=>`<button class="btn" data-action="${id}">${amap[id].title}</button>`).join('')}</div>`);return;}
 if(t.dataset.transfer){const r=t.dataset.transfer,other=r==='main'?'sub':'main';const id={cspine:'cspine',pressure:'pressure',cpr:'cpr',bvm:'bvm'}[S.holds[r]];if(id)openAction(id,other);return;}
 if(t.dataset.release){const r=t.dataset.release,h=S.holds[r];if(['cspine','pressure'].includes(h)){issue(S,'release_'+h,`${ROLES[r]}未確認接手就要放開${holdLabel(h)}；必須先交接。`,true);toast('需要先由另一位接手，這項持續處置不能直接放開。');}else{S.holds[r]=null;if(h==='cpr')S.cpr.pauseSince=S.time;addLog(S,r,`暫停${holdLabel(h)}，請盡快接續必要處置。`,'info');}updateAll();return;}
 if(t.dataset.cancel){const r=t.dataset.cancel,task=S.tasks[r];if(task){for(const r2 of ['main','sub'])if(S.tasks[r2]?.id===task.id)S.tasks[r2]=null;addLog(S,r,'中止：'+amap[task.id].title,'warning');updateAll();}return;}
 if(t.dataset.inject){checkpoints.push({t:S.time,state:structuredClone(S)});inject(S,t.dataset.inject);closeDialog();updateAll();persist();return;}
 if(t.dataset.say){if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(amap[t.dataset.say].voice);u.lang='zh-TW';u.rate=.88;speechSynthesis.cancel();speechSynthesis.speak(u);}else toast('這個瀏覽器不支援語音播放，請依文字練口述。');return;}
 if(t.dataset.rewind){const target=Number(t.dataset.rewind);const cp=[...checkpoints].reverse().find(c=>c.t<target)||checkpoints[0];if(cp){S=structuredClone(cp.state);S.ended=false;S.paused=true;addLog(S,'系統','從錯誤前的狀態重新演練；按「繼續」恢復時間。','info');view='sim';render();window.scrollTo(0,0);}return;}
 if(t.dataset.history){const h=history.find(x=>x.id===Number(t.dataset.history));showDialog(`<div class="dialog-head"><h2>${esc(h.name)} · 操作回放</h2><button class="close" data-cmd="close" aria-label="關閉">×</button></div><div class="dialog-body"><p>漏項：${h.missing.map(esc).join('、')||'無'}。</p>${logs(h.log)}</div>`,'wide');}
 if(t.dataset.card!==undefined){cardIndex=Number(t.dataset.card);cardHidden=false;render();return;}
});
document.addEventListener('input',e=>{if(e.target.id==='action-search'){search=e.target.value;$('#action-list').innerHTML=actionList();}});
document.addEventListener('change',e=>{if(e.target.id==='speed'&&S){S.speed=Number(e.target.value);persist();}});
document.addEventListener('submit',e=>{if(e.target.id==='physical-form'){e.preventDefault();const fd=new FormData(e.target);for(const k of ['rate','depth','recoil','placement','ventilation'])S.physical[k]=fd.get(k)||'';persist();saveHistory();render();toast('已儲存實測結果。');}});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&modal){closeDialog();return;}
 if(e.key==='Tab'&&modal){const els=[...$('#drawer-root').querySelectorAll('button,input,select,a[href]')].filter(el=>!el.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
 if(e.code==='Space'&&view==='sim'&&!modal&&!e.repeat&&!['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();cmd('compression');}
 if(e.key==='Enter'&&e.target.dataset.zone)e.target.click();
});
function checkLimit(){if(S?.limit&&S.time>=S.limit&&!S.ended){issue(S,'custom_time','自訂壓力練習時間已到。這是自訂時間，不是本班正式時限。');finish();}}
setInterval(()=>{if(S&&!S.ended&&!S.paused&&view==='sim'){const n=S.log.length;advance(S,S.speed);if(S.log.length!==n)updateAll();else updateLive();if(S.time%5===0)persist();checkLimit();}},1000);
window.addEventListener('beforeunload',persist);
if(new URLSearchParams(window.location.search).get('start')==='beginner'){view='intro';S=createIntro();}
render();
